  const state = {name:'AK Studio Pro',id:'ak-studio-pro',author:'tu-usuario',version:'1.0.0',base:'StudioBlue',min_version:'2.3.0',description:'Un espacio de edición personalizado para AK Screen.',colors:{...STUDIO_COLORS},metrics:{...DEFAULT_METRICS},clip_colors:{...CLIP_COLORS},asset_colors:{...ASSET_COLORS},layout:buildWorkspaceLayout('Editing'),workspace:'Editing',cssEnabled:true,css:DEFAULT_CSS,includeCss:true,includePreview:true,previewBgOpacity:22,files:{},icons:[],license:'',previewMode:'editor'};
  let captureWaiter = null;  const objectUrls = new Set();
